class Solution {
    public int minRectanglesToCoverPoints(int[][] points, int w) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] p : points) set.add(p[0]);
        int ans = 1, cur = set.first();
        boolean first = true;
        for (int x : set) {
            if (first) { first = false; continue; }
            if (x > cur + w) { ans++; cur = x; }
        }
        return ans;
    }
}

